4. // Cache - Specifications
5. //
6. // This file contains the CacheView type, invariant, spec transition functions,
7. // and View trait implementations for Cache and CacheGuard.
8. 
9. verus! {
10. 
11. //==================================================================================================
12. // Cache-specific External Type Specifications
13. //==================================================================================================
14. 
15. // CacheEntry is a private internal type.
16. #[verifier::reject_recursive_types(V)]
17. #[verifier::external_type_specification]
18. struct ExCacheEntry<V>(crate::CacheEntry<V>);
19. 
20. // CacheGuard wraps &mut V; Verus cannot handle &mut in struct fields,
21. // so we declare it as an external type.
22. #[verifier::reject_recursive_types(V)]
23. #[verifier::external_type_specification]
24. #[verifier::external_body]
25. pub struct ExCacheGuard<'a, V>(crate::CacheGuard<'a, V>);
26. 
27. //==================================================================================================
28. // Cache abstraction functions (connecting concrete fields to abstract CacheView)
29. //==================================================================================================
30. 
31. // Project BTreeMap<K, CacheEntry<V>> contents to Map<K, V> by extracting CacheEntry::value.
32. // Closed: CacheEntry is crate-private, so the body can't appear in pub open functions.
33. spec fn cache_contents_of<K, V>(entries: alloc::collections::BTreeMap<K, CacheEntry<V>>) -> Map<K, V> {
34.     Map::new(
35.         |k: K| btreemap_view_spec(entries).dom().contains(k),
36.         |k: K| btreemap_view_spec(entries)[k].value,
37.     )
38. }
39. 
40. // LRU ordering from entries: sorted by last_used ascending.
41. // For empty entries, definitionally Seq::empty(); otherwise uninterpreted.
42. spec fn cache_lru_of<K, V>(entries: alloc::collections::BTreeMap<K, CacheEntry<V>>) -> Seq<K> {
43.     if btreemap_view_spec(entries).dom().len() == 0 {
44.         Seq::empty()
45.     } else {
46.         cache_lru_of_nonempty(entries)
47.     }
48. }
49. 
50. uninterp spec fn cache_lru_of_nonempty<K, V>(entries: alloc::collections::BTreeMap<K, CacheEntry<V>>) -> Seq<K>;
51. 
52. //==================================================================================================
53. // CacheView - Abstract Specification Model
54. //==================================================================================================
55. 
56. /// Abstract view of a bounded LRU cache.
57. ///
58. /// - `contents`: the key-value mapping of all cached entries.
59. /// - `capacity`: maximum number of entries.
60. /// - `lru_order`: keys ordered from LRU (index 0) to MRU (last element).
61. #[verifier::ext_equal]
62. #[verifier::reject_recursive_types(K)]
63. #[verifier::reject_recursive_types(V)]
64. pub struct CacheView<K, V> {
65.     pub contents: Map<K, V>,
66.     pub capacity: nat,
67.     pub lru_order: Seq<K>,
68. }
69. 
70. impl<K, V> CacheView<K, V> {
71. 
72.     //----------------------------------------------------------------------------------------------
73.     // Well-formedness Invariant
74.     //----------------------------------------------------------------------------------------------
75. 
76.     /// Well-formedness invariant for the abstract cache state.
77.     pub open spec fn inv(&self) -> bool {
78.         // Size never exceeds capacity.
79.         &&& self.contents.dom().len() <= self.capacity
80.         // LRU order has no duplicates.
81.         &&& self.lru_order.no_duplicates()
82.         // LRU order contains exactly the stored keys.
83.         &&& self.lru_order.to_set() == self.contents.dom()
84.         // Explicit cardinality link (helps the solver).
85.         &&& self.lru_order.len() == self.contents.dom().len()
86.     }
87. 
88.     //----------------------------------------------------------------------------------------------
89.     // Helper Spec Functions
90.     //----------------------------------------------------------------------------------------------
91. 
92.     /// Move `key` to the most-recently-used position (end of the sequence).
93.     /// Preserves all other elements and their relative order.
94.     pub open spec fn move_to_mru(self, key: K) -> Seq<K> {
95.         self.lru_order.filter(|k: K| k != key).push(key)
96.     }
97. 
98.     //----------------------------------------------------------------------------------------------
99.     // Spec Transition Functions
100.     //----------------------------------------------------------------------------------------------
101. 
102.     /// Spec transition for `Cache::new`.
103.     pub open spec fn spec_new(capacity: nat) -> CacheView<K, V> {
104.         CacheView {
105.             contents: Map::empty(),
106.             capacity,
107.             lru_order: Seq::empty(),
108.         }
109.     }
110. 
111.     /// Spec transition for `Cache::get`.
112.     /// Returns the updated cache state and the lookup result.
113.     pub open spec fn spec_get(self, key: K) -> (CacheView<K, V>, Option<V>) {
114.         if self.contents.dom().contains(key) {
115.             (CacheView {
116.                 lru_order: self.move_to_mru(key),
117.                 ..self
118.             }, Some(self.contents[key]))
119.         } else {
120.             (self, None)
121.         }
122.     }
123. 
124.     /// Spec transition for `Cache::put`.
125.     pub open spec fn spec_put(self, key: K, value: V) -> CacheView<K, V> {
126.         if self.capacity == 0 {
127.             // Zero-capacity cache: no-op.
128.             self
129.         } else if self.contents.dom().contains(key) {
130.             // Overwrite existing key: replace value, refresh recency.
131.             CacheView {
132.                 contents: self.contents.insert(key, value),
133.                 lru_order: self.move_to_mru(key),
134.                 ..self
135.             }
136.         } else if self.contents.dom().len() >= self.capacity {
137.             // At capacity with new key: evict LRU victim, then insert.
138.             let victim = self.lru_order[0];
139.             CacheView {
140.                 contents: self.contents.remove(victim).insert(key, value),
141.                 lru_order: self.lru_order.subrange(1, self.lru_order.len() as int).push(key),
142.                 ..self
143.             }
144.         } else {
145.             // Below capacity with new key: insert directly.
146.             CacheView {
147.                 contents: self.contents.insert(key, value),
148.                 lru_order: self.lru_order.push(key),
149.                 ..self
150.             }
151.         }
152.     }
153. 
154.     /// Spec transition for `Cache::remove`.
155.     pub open spec fn spec_remove(self, key: K) -> CacheView<K, V> {
156.         if self.contents.dom().contains(key) {
157.             CacheView {
158.                 contents: self.contents.remove(key),
159.                 lru_order: self.lru_order.filter(|k: K| k != key),
160.                 ..self
161.             }
162.         } else {
163.             // Key absent: no-op.
164.             self
165.         }
166.     }
167. 
168.     /// Spec transition for `Cache::clear`.
169.     pub open spec fn spec_clear(self) -> CacheView<K, V> {
170.         CacheView {
171.             contents: Map::empty(),
172.             lru_order: Seq::empty(),
173.             ..self  // capacity preserved
174.         }
175.     }
176. }
177. 
178. //==================================================================================================
179. // View Implementation for Cache
180. //==================================================================================================
181. 
182. // Cache View — connects concrete BTreeMap state to abstract CacheView.
183. // Closed: CacheEntry is private, so the body can't be pub open.
184. // Within this crate, use reveal(Cache::view) to expose the structure in proofs.
185. impl<K: Ord + Clone, V> View for Cache<K, V> {
186.     type V = CacheView<K, V>;
187. 
188.     closed spec fn view(&self) -> CacheView<K, V> {
189.         CacheView {
190.             contents: cache_contents_of(self.entries),
191.             capacity: self.capacity as nat,
192.             lru_order: cache_lru_of(self.entries),
193.         }
194.     }
195. }
196. 
197. //==================================================================================================
198. // View Implementation for CacheGuard
199. //==================================================================================================
200. 
201. // CacheGuard is external_body (Verus limitation: &mut in struct fields),
202. // so the view is uninterpreted. Constraints come from get/deref ensures.
203. impl<'a, V> View for CacheGuard<'a, V> {
204.     type V = V;
205. 
206.     uninterp spec fn view(&self) -> V;
207. }
208. 
209. } // verus!
